"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { useApi } from "@/hooks/useApi";
import { loginUser } from "@/services/authService";
import HeaderTag from "@/components//Header-tag";
import { Eye, EyeOff } from "lucide-react";

export default function LoginPage() {
    const router = useRouter();
    const { request, loading, error } = useApi();

    const [username, setUsername] = useState("");
    const [password, setPassword] = useState("");
    const [localError, setLocalError] = useState("");
    const [showPassword, setShowPassword] = useState(false);

    const handleLogin = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setLocalError("");

        try {
            const data = await loginUser(request, username, password);

            if (data.token) {
                localStorage.setItem("token", data.token);
                localStorage.setItem("username", data.username || username);
            }

            router.push("/studentDashboard");
        } catch {
            setLocalError("Invalid credentials or server error.");
        }
    };

    return (
        <div className="min-h-screen bg-[#f4f6fb]">

            {/* ✅ Reusable Header */}
            <HeaderTag title="Login" breadcrumb="Login" />

            {/* Login Card */}
            <div className="flex justify-center py-10 px-4">
                <div className="w-full max-w-md bg-white rounded-2xl shadow-lg p-8">

                    <h2 className="text-xl font-semibold text-[#1f2a44] mb-6 text-center">
                        Welcome Back
                    </h2>

                    {(error || localError) && (
                        <p className="text-red-500 text-sm mb-4 text-center">
                            {error || localError}
                        </p>
                    )}

                    <form onSubmit={handleLogin} className="space-y-5">

                        {/* Username */}
                        <div className="relative">
                            <label className="block text-sm text-gray-600 mb-1">
                                Username
                            </label>

                            <input
                                type="text"
                                className="w-full border border-gray-300 rounded-md px-3 py-2
                focus:ring-2 focus:ring-blue-500 focus:border-blue-500
                outline-none transition text-sm"
                                placeholder="Enter your username"
                                value={username}
                                onChange={(e) => setUsername(e.target.value)}
                                required
                            />
                        </div>

                        {/* Password */}
                        <div className="relative">
                            <label className="block text-sm text-gray-600 mb-1">
                                Password
                            </label>

                            <input
                                type={showPassword ? "text" : "password"}
                                className="w-full border border-gray-300 rounded-md px-3 py-2 pr-10
                focus:ring-2 focus:ring-blue-500 focus:border-blue-500
                outline-none transition text-sm"
                                placeholder="Enter your password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                required
                            />

                            {/* Show / Hide Button */}
                            <button
                                type="button"
                                onClick={() => setShowPassword(!showPassword)}
                                className="absolute right-3 top-9 text-gray-500 hover:text-gray-700"
                            >
                                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                            </button>
                        </div>

                        {/* Button */}
                        <button
                            type="submit"
                            disabled={loading}
                            className="w-full py-2.5 rounded-lg text-white font-medium text-sm
              bg-linear-to-r from-blue-600 to-purple-600
              hover:opacity-90 transition disabled:opacity-60"
                        >
                            {loading ? "Logging In..." : "Log In"}
                        </button>
                    </form>
                </div>
            </div>
        </div>
    );
}
